insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('e05d9ecc-6332-590c-af2b-e2280cf9e683',(select id from public.prophets where slug='adam' limit 1),'السياق والرسالة','Context and mission','آدم أبو البشر، خلقه الله وعلّمه الأسماء وأسجد له الملائكة، ثم بدأ ابتلاءه في الجنة بالتكليف والنهي. تاب بعد الزلة فكان في قصته أصل معنى التوبة والرجوع إلى الله.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',4) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('17bab012-23cd-5dfb-81c1-491435efa4bd',(select id from public.prophets where slug='adam' limit 1),'المحطات والابتلاءات','Key events and trials','دعا آدم ذريته إلى التوحيد وحذرهم من عداوة الشيطان، وتناقلت ذريته معنى العبادة والعمارة بالحق. لا نثبت من تفاصيل حياته إلا ما دل عليه الوحي أو اشتهر بدليل معتبر.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',5) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('546bfbca-1905-535f-ac5f-e2c82c6ee5c7',(select id from public.prophets where slug='adam' limit 1),'الدروس والضوابط','Lessons and evidence boundaries','أبرز دروس قصته أن الخطأ لا يغلق باب الرحمة إذا صدقت التوبة، وأن العلم والتكليف والاختيار مسؤولية، وأن عداوة الشيطان تستلزم يقظة دائمة. المراجع القرآنية المختصرة: سور البقرة والأعراف وطه.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',6) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('7d97809b-7893-5549-b864-3e7185072637',(select id from public.prophets where slug='idris' limit 1),'السياق والرسالة','Context and mission','ذكره القرآن بالصديقية والرفعة، وهو من أوائل الأنبياء بعد آدم. تعرض قصته نموذجًا للنبي الذي جمع صدق الإيمان مع الصبر والعمل النافع.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',4) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('780ca2a9-54b3-58b1-92fa-a3c89f699f2a',(select id from public.prophets where slug='idris' limit 1),'المحطات والابتلاءات','Key events and trials','تتداول كتب القصص أخبارًا كثيرة عن إدريس، لكن الثابت في القرآن اختصارًا هو صدقه ورفع مكانته؛ لذلك يميز هذا القسم بين الثابت والمشهور ولا يجزم بما لا دليل عليه.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',5) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('53ea0f66-e764-556e-a97b-23af5c05dda1',(select id from public.prophets where slug='idris' limit 1),'الدروس والضوابط','Lessons and evidence boundaries','تعلم قصته قيمة الصدق، ورفعة العلم النافع، والصبر الهادئ في طريق الإصلاح دون إضافة تفاصيل غير موثقة. المراجع القرآنية المختصرة: سورة مريم والأنبياء.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',6) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('f5e7d619-f3e6-5ac7-824e-fea59c82f342',(select id from public.prophets where slug='nuh' limit 1),'السياق والرسالة','Context and mission','لبث نوح في قومه يدعوهم إلى عبادة الله وحده زمنًا طويلًا، واستخدم أساليب متنوعة في الدعوة، فدعاهم ليلًا ونهارًا وسرًا وجهارًا.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',4) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('11b6679d-5bfb-51eb-80ec-bb2aaeee02a8',(select id from public.prophets where slug='nuh' limit 1),'المحطات والابتلاءات','Key events and trials','كذب قومه وسخروا منه، ثم جاء أمر الله بصنع السفينة، فحمل فيها المؤمنين ومن كل زوجين اثنين. كان الطوفان آية على أن النجاة بالإيمان لا بالنسب، وانتهت القصة باستقرار السفينة على الجودي.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',5) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('11ff58f1-3221-59d3-9b32-50cc6ecbd8c2',(select id from public.prophets where slug='nuh' limit 1),'الدروس والضوابط','Lessons and evidence boundaries','الصبر الطويل، تنويع الخطاب، عدم الاغترار بالقرابة مع انقطاع العمل، والثقة بوعد الله عند اشتداد الاستهزاء. المراجع القرآنية المختصرة: سور هود ونوح والمؤمنون والقمر.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',6) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
