insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('ea42ab3e-0957-5dc9-ba1a-11be5d3616f3',(select id from public.prophets where slug='hud' limit 1),'الدروس والضوابط','Lessons and evidence boundaries','القوة بلا شكر تتحول إلى طغيان، والاستغفار سبب للمدد، والنجاة مرتبطة بالإيمان لا بالقدرة المادية. المراجع القرآنية المختصرة: سور الأعراف وهود والأحقاف والفجر.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',6) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('ab806d26-ae09-5348-aa0a-dbab7246c25d',(select id from public.prophets where slug='salih' limit 1),'السياق والرسالة','Context and mission','دعا صالح ثمود إلى عبادة الله، وذكّرهم بنعمة العمران في الجبال والسهول، وجاءتهم الناقة آية واختبارًا في احترام حدود الله.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',4) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('48054e53-8837-5451-b4b1-7f66bf6c3137',(select id from public.prophets where slug='salih' limit 1),'المحطات والابتلاءات','Key events and trials','عقرت ثمود الناقة وتآمروا على صالح، فجاءتهم الصيحة والرجفة بعد الإنذار، ونجى الله صالحًا والمؤمنين من قومه.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',5) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
