insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('42792cb6-1ade-50e3-a3c3-7d1cd1b477c8',(select id from public.prophets where slug='ibrahim' limit 1),'المحطات والابتلاءات','Key events and trials','كسر الأصنام فحاجه قومه وألقوه في النار فجعلها الله بردًا وسلامًا. هاجر، وبنى البيت مع إسماعيل، وابتلي بالأمر بذبح ابنه فاستجاب ففداه الله.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',5) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('11fed454-40f6-5f3d-af0f-f0fbc8c4a16d',(select id from public.prophets where slug='ibrahim' limit 1),'الدروس والضوابط','Lessons and evidence boundaries','اليقين يحرر القلب من ضغط البيئة، والابتلاء يكشف صدق المحبة، وبناء البيت ارتبط بالتوحيد والدعاء وخدمة الناس. المراجع القرآنية المختصرة: سور البقرة وإبراهيم والأنبياء والصافات والأنعام.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',6) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('9d9baeca-51da-565f-81fa-4ec45beb4732',(select id from public.prophets where slug='lut' limit 1),'السياق والرسالة','Context and mission','أرسل لوط إلى قوم اشتهروا بالفاحشة وقطع الطريق ورفض الموعظة، فدعاهم إلى الطهارة وترك العدوان.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',4) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
