insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('9dd59145-153b-5734-98f6-8000790bd5a3',(select id from public.prophets where slug='ismail' limit 1),'السياق والرسالة','Context and mission','نشأ إسماعيل في واد غير ذي زرع، فكان رمزًا للصبر والصدق والوفاء بالوعد، وتولى مع أبيه إبراهيم رفع قواعد الكعبة.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',4) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
