insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('306df94b-fffb-55ba-b454-f4a2740c76e3',(select id from public.prophets where slug='ishaq' limit 1),'الدروس والضوابط','Lessons and evidence boundaries','الأمل لا تحده الأسباب المعتادة، والبركة في الذرية مرتبطة بالصلاح، والبشارة تستدعي الشكر والعمل. المراجع القرآنية المختصرة: سور هود والأنعام والصافات ومريم.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',6) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
