insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('47862ada-65c6-5aa1-9337-192dca641b3d',(select id from public.prophets where slug='yaqub' limit 1),'الدروس والضوابط','Lessons and evidence boundaries','الصبر الجميل ليس إنكار الحزن، بل توجيهه إلى الله، وحسن الظن لا يناقض الأخذ بالأسباب والنصيحة. المراجع القرآنية المختصرة: سور البقرة ويوسف ومريم.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',6) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
