insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('1b39e8bf-14e0-521e-b63b-f2310e25821e',(select id from public.prophets where slug='muhammad' limit 1),'السياق والرسالة','Context and mission','خاتم الأنبياء، بعثه الله رحمة للعالمين بالقرآن والتوحيد، فبدأ بالدعوة في مكة ثم بنى مجتمع المدينة على الإيمان والعهد والعدل.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',4) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('e5d8cd86-b351-5ee5-bfd3-f02fb84119ad',(select id from public.prophets where slug='muhammad' limit 1),'المحطات والابتلاءات','Key events and trials','واجه التكذيب والهجرة والحروب والصلح، وفتح مكة متواضعًا، وأدى الأمانة وترك للأمة كتاب الله وسنته الصحيحة.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',5) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('c10e407e-0987-55af-8861-31c3326ddb8f',(select id from public.prophets where slug='muhammad' limit 1),'الدروس والضوابط','Lessons and evidence boundaries','الرحمة مع الثبات، الوفاء بالعهد، الشورى، العفو عند القدرة، وربط العبادة بإصلاح المجتمع. المراجع القرآنية المختصرة: سور الأحزاب والفتح والتوبة ومحمد والضحى.','Original editorial module based on Qur’anic narratives and verified Islamic references; details outside established evidence are not asserted.','biography',6) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.battles (id,name_ar,name_en,slug,description_ar,description_en,date_hijri,location_ar,location_en,order_num,published,metadata) values ('8fe26beb-3096-5bf0-9e71-9631b6a3276a','غزوة الأبواء (ودّان)','Expedition of Al-Abwa/Waddan','waddan','كانت أولى الخرجات العسكرية المنظمة بعد الهجرة، وانتهت بموادعة بني ضمرة دون قتال.','Original chronological summary prepared for Zikr from established sira references.','2 هـ','الأبواء وودّان','Arabia',101,true,'{"lesson_ar":"تعلم التخطيط وفتح أبواب السلم قبل الصدام.","source_note":"Curated summary; consult specialized sira works for variant reports."}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,description_ar=excluded.description_ar,description_en=excluded.description_en,date_hijri=excluded.date_hijri,location_ar=excluded.location_ar,location_en=excluded.location_en,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
